head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var rowJSON = {
        "addr": "서울시",
        "name": "손예진",
        "rowStatus": "R"
    };
    //popup에 넘길 data객체. 
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array" 
        data: rowJSON, // 전달 데이터 객체. 
        name: "paramTest" // 변수명. popup에서 $w.getParameter( "paramTest" )로 깨내올 수 있다. 
    };
    var options = {
        id: "popup1",
        type: "wframePopup",
        width: 300 + "px",
        height: 300 + "px",
        top: 100 + "px",
        left: 100 + "px",
        popupName: "Test111",
        modal: true,
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        useMaximize: true,
        dataObject: dataObj
    };
    $p.openPopup("wframePopup_WPFF-331_(WSQ-3821)_sub_auto.xml", options);
};
scwin.checkVal = function() {
    return localStorage.getItem('log') == '서울시';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'popup1_wframe_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
